# Implémentation complète

## Pile avec liste Python

```python
class Pile:
    def __init__(self):
        self._elements = []

    def empiler(self, e):
        self._elements.append(e)

    def depiler(self):
        assert not self.est_vide(), "Pile vide"
        return self._elements.pop()

    def sommet(self):
        assert not self.est_vide(), "Pile vide"
        return self._elements[-1]

    def est_vide(self):
        return len(self._elements) == 0

    def __len__(self):
        return len(self._elements)

    def __repr__(self):
        return f"Pile({list(self._elements)})"
```

## File avec deque

```python
from collections import deque

class File:
    def __init__(self):
        self._elements = deque()

    def enfiler(self, e):
        self._elements.append(e)

    def defiler(self):
        assert not self.est_vide(), "File vide"
        return self._elements.popleft()

    def tete(self):
        assert not self.est_vide(), "File vide"
        return self._elements[0]

    def est_vide(self):
        return len(self._elements) == 0

    def __len__(self):
        return len(self._elements)
```

> 💡 Utiliser `deque` plutôt que `list` pour les files car `pop(0)` sur une liste est en O(n) alors que `popleft()` sur deque est en O(1).
